<?php
declare(strict_types=1);
require_once __DIR__.'/contact-core.php';
function lead_id(string $id): string {if(!preg_match('/^[a-f0-9]{32}$/D',$id))throw new InvalidArgumentException('Nieprawidłowe zapytanie.');return $id;}
function lead_load(string $id): array {$id=lead_id($id);$file=contact_store().'/'.$id.'.json';if(!is_file($file))throw new InvalidArgumentException('Nie znaleziono zapytania.');$lead=json_decode(file_get_contents($file),true,512,JSON_THROW_ON_ERROR);return ['id'=>$id,...$lead,'leadStatus'=>$lead['leadStatus']??'new','notes'=>$lead['notes']??'','version'=>$lead['version']??1,'photos'=>$lead['photos']??[]];}
function lead_list(): array {$items=[];$counts=['all'=>0,'new'=>0,'contacted'=>0,'closed'=>0];foreach(glob(contact_store().'/*.json') as $file){$id=basename($file,'.json');if(!preg_match('/^[a-f0-9]{32}$/D',$id))continue;$r=lead_load($id);$d=$r['data'];$status=$r['leadStatus'];$counts['all']++;$counts[$status]=($counts[$status]??0)+1;$items[]=['id'=>$id,'receipt'=>$r['receipt'],'createdAt'=>$r['createdAt'],'name'=>$d['imie']??'','email'=>$d['email']??'','phone'=>$d['telefon']??'','location'=>$d['lokalizacja']??'','area'=>$d['powierzchnia']??'','leadStatus'=>$status,'mailStatus'=>$r['status'],'attachmentCount'=>$r['attachmentCount']??0];}usort($items,fn($a,$b)=>strcmp($b['createdAt'],$a['createdAt'])?:strcmp($b['id'],$a['id']));return ['items'=>$items,'counts'=>$counts];}
function lead_update(string $id,array $data): array {$id=lead_id($id);$status=$data['leadStatus']??'';$notes=$data['notes']??'';if(!in_array($status,['new','contacted','closed'],true)||!is_string($notes)||mb_strlen($notes)>5000)throw new InvalidArgumentException('Wybierz status i notatkę do 5000 znaków.');$lock=fopen(contact_store().'/sending.lock','c+');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('Spróbuj ponownie za chwilę.');try{$lead=lead_load($id);if(($data['version']??0)!==$lead['version'])throw new RuntimeException('Zapytanie zmieniono w innym oknie. Odśwież widok przed zapisaniem.');$lead['leadStatus']=$status;$lead['notes']=trim($notes);$lead['version']++;$lead['updatedAt']=gmdate('c');contact_write(contact_store().'/'.$id.'.json',$lead);return $lead;}finally{flock($lock,LOCK_UN);fclose($lock);}}
function lead_photo_path(string $id,int $number): string {$lead=lead_load($id);if($number<1||$number>5||!array_filter($lead['photos'],fn($p)=>(int)$p['number']===$number))throw new InvalidArgumentException('Nie znaleziono zdjęcia.');$path=contact_store().'/files/'.lead_id($id).'/'.$number.'.jpg';if(!is_file($path))throw new InvalidArgumentException('Nie znaleziono zdjęcia.');return $path;}
